-- Speak prompts can be study items: a prompt answered "Not quite" in a session
-- comes back in reviews. A new arm on the study_items exclusive arc, as the
-- design requires for any new content kind — never a payload column.
--
-- Generated by drizzle-kit, then made idempotent by hand. Additive: one nullable
-- column, its foreign key and unique index, and the arc check widened to count
-- it. Every existing row has the new column NULL, so it still has exactly one
-- target and the re-added check holds.

ALTER TABLE "study_items" DROP CONSTRAINT IF EXISTS "study_items_exactly_one_target";--> statement-breakpoint
ALTER TABLE "study_items" ADD COLUMN IF NOT EXISTS "speak_step_id" text;--> statement-breakpoint
DO $$ BEGIN
  ALTER TABLE "study_items" ADD CONSTRAINT "study_items_speak_step_id_speak_steps_id_fk" FOREIGN KEY ("speak_step_id") REFERENCES "public"."speak_steps"("id") ON DELETE cascade ON UPDATE no action;
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;--> statement-breakpoint
CREATE UNIQUE INDEX IF NOT EXISTS "study_items_speak_step_unique" ON "study_items" USING btree ("speak_step_id") WHERE "study_items"."speak_step_id" is not null;--> statement-breakpoint
ALTER TABLE "study_items" ADD CONSTRAINT "study_items_exactly_one_target" CHECK (num_nonnulls("study_items"."kana_id", "study_items"."kanji_id", "study_items"."word_id", "study_items"."grammar_point_id", "study_items"."sentence_id", "study_items"."phonetic_series_id", "study_items"."dialogue_id", "study_items"."speak_step_id") = 1);
